  (r : Fin (?m.412 + 1) → ?m.409),
  have U₀ := (splitHalfRowWiseInterleavedWords u).1;
  have U₁ := (splitHalfRowWiseInterleavedWords u).2;
  have r_init := Fin.init r;
  multilinearCombine u r = multilinearCombine (affineLineEvaluation U₀ U₁ (r (Fin.last ?m.412))) r_init

